import os
os.chdir(os.path.dirname(os.path.abspath(__file__)))
import json,re
segs=json.load(open('segs.json'))+json.load(open('new.json'))
base=len(json.load(open('segs.json')))
en={}
for l in [l.rstrip('\n') for l in open('en.txt',encoding='utf-8') if l.strip()]:
    i,t=l.split('\t',1);en[int(i)]=t
for l in [l.rstrip('\n') for l in open('en2.txt',encoding='utf-8') if l.strip()]:
    i,t=l.split('\t',1);en[base+int(i)]=t
idx={k:i for i,k in enumerate(segs)}
en[idx['{0}장']]='{0} photos'
H=re.compile(r'[\uac00-\ud7a3]')
NH=r'([^\uac00-\ud7a3]+?)'
exact={};pats=[]
def addpat(k2,v):
    lit=re.sub(r'\{\d+\}','',k2);nh=len(H.findall(lit))
    parts=re.split(r'(\{\d+\})',k2);rx=''
    for j,p in enumerate(parts):
        if re.fullmatch(r'\{\d+\}',p):
            prev=parts[j-1][-1:] if j>0 else '';nxt=parts[j+1][:1] if j+1<len(parts) else ''
            glued=bool(H.match(prev) or H.match(nxt))
            rx+=NH if (glued and nh<=4) else r'(.*?)'
        else:rx+=re.escape(p)
    pats.append(['^'+rx+'$',v,len(lit)])
for i,k in enumerate(segs):
    v=en[i]
    if v=='-':continue
    v=v.replace('\\n','\n');k2=k.replace('\\n','\n').replace('\\"','"')
    variants=[k2]+([k2[2:]] if k2.startswith('· ') else [])
    for kk in variants:
        vv=v if kk==k2 else v.strip()
        if kk!=k2 and vv.startswith('· '):vv=vv[2:]
        if re.search(r'\{\d+\}',kk):addpat(kk,vv)
        else:exact.setdefault(kk,vv)
