frag=[k for k in exact if k and not H.match(k[0]) and H.search(k) and len(k)>=3]
frag.sort(key=len,reverse=True)
js='window.I18N='+json.dumps({'exact':exact,'pats':[[p[0],p[1]] for p in pats],'frag':frag},ensure_ascii=False)+';\n'
